#include "producer_producer.h"

// Do not edit this file as it will be overwritten if HAMR codegen is rerun

void producer_producer_initialize(void);
void producer_producer_notify(microkit_channel channel);
void producer_producer_timeTriggered(void);

volatile sb_queue_int32_t_1_t *sample_queue_1;

#define PORT_FROM_MON 0

bool put_sample(const int32_t *data) {
  sb_queue_int32_t_1_enqueue((sb_queue_int32_t_1_t *) sample_queue_1, (int32_t *) data);

  return true;
}

void init(void) {
  printf("%s | INIT!\n", microkit_name);

  sb_queue_int32_t_1_init((sb_queue_int32_t_1_t *) sample_queue_1);

  producer_producer_initialize();

  microkit_notify(PORT_FROM_MON);
}

void notified(microkit_channel channel) {
  switch (channel) {
    case PORT_FROM_MON:
      producer_producer_timeTriggered();
      break;
    default:
      producer_producer_notify(channel);
  }
}
